"""B1 independent fictional OOXML generated by the installed python-docx."""
from io import BytesIO
from types import SimpleNamespace
from uuid import uuid4
from zipfile import ZipFile, ZIP_DEFLATED
from xml.etree import ElementTree as ET

from docx import Document
from docx.enum.style import WD_STYLE_TYPE
from docx.oxml import OxmlElement
from docx.oxml.ns import qn
import pytest

from cn_contract.config import load_settings
from cn_contract.domain import BaselineView
from cn_contract.documents.docx_adapter import parse_docx
from cn_contract.security import ServiceError

W = 'http://schemas.openxmlformats.org/wordprocessingml/2006/main'
REL = 'http://schemas.openxmlformats.org/package/2006/relationships'
CT = 'http://schemas.openxmlformats.org/package/2006/content-types'


def office_document():
    document = Document()
    document.add_paragraph('SYNTHETIC buyer owes CNY 14200.')
    document.add_paragraph('SYNTHETIC delivery in 31 days.')
    document.add_paragraph('SYNTHETIC no automatic renewal.')
    return document


def saved(document):
    output = BytesIO()
    document.save(output)
    return output.getvalue()


def edited(data, changes):
    """Mutate independent test package bytes, never an original or an audit bundle."""
    with ZipFile(BytesIO(data)) as package:
        parts = {name: package.read(name) for name in package.namelist()}
    for name, change in changes.items():
        if callable(change):
            root = ET.fromstring(parts[name])
            change(root)
            parts[name] = ET.tostring(root, encoding='utf-8', xml_declaration=True)
        else:
            parts[name] = change
    output = BytesIO()
    with ZipFile(output, 'w', compression=ZIP_DEFLATED) as package:
        for name, value in parts.items():
            package.writestr(name, value)
    return output.getvalue()


def parse(data, baseline=BaselineView.ORIGINAL):
    version = SimpleNamespace(id=uuid4(), baseline_view=baseline)
    return parse_docx(data, version, load_settings())


def test_plain_python_docx_auxiliaries_do_not_create_material_gap():
    document = office_document()
    document.add_table(rows=1, cols=1).cell(0, 0).text = 'SYNTHETIC guarantee 400.'
    data = saved(document)
    original = bytes(data)
    result = parse(data)
    assert [anchor.quote for anchor in result.anchors] == [
        'SYNTHETIC buyer owes CNY 14200.', 'SYNTHETIC delivery in 31 days.',
        'SYNTHETIC no automatic renewal.', 'SYNTHETIC guarantee 400.',
    ]
    assert result.unsupported_parts == ()
    assert result.quality_issues == ()
    for name in ('word/styles.xml', 'word/settings.xml', 'word/fontTable.xml',
                 'word/theme/theme1.xml', 'word/numbering.xml', 'customXml/item1.xml',
                 'docProps/thumbnail.jpeg'):
        assert f'{name}:metadata_read' in result.parts
    assert len(result.parts) == 17
    assert data == original


@pytest.mark.parametrize('kind', [WD_STYLE_TYPE.PARAGRAPH, WD_STYLE_TYPE.CHARACTER])
@pytest.mark.parametrize('property_name', ['vanish', 'webHidden'])
def test_referenced_inherited_hidden_style_never_enters_anchor(kind, property_name):
    document = office_document()
    base = document.styles.add_style('SyntheticHiddenBase', kind)
    flag = OxmlElement(f'w:{property_name}')
    base.element.get_or_add_rPr().append(flag)
    derived = document.styles.add_style('SyntheticHiddenDerived', kind)
    derived.base_style = base
    paragraph = document.add_paragraph()
    if kind == WD_STYLE_TYPE.PARAGRAPH:
        paragraph.style = derived
        paragraph.add_run('SYNTHETIC hidden CNY 987654.')
    else:
        paragraph.add_run('SYNTHETIC visible prefix. ')
        paragraph.add_run('SYNTHETIC hidden CNY 987654.', style=derived)
    result = parse(saved(document))
    assert all('987654' not in anchor.quote for anchor in result.anchors)
    assert any(':hidden:' in part for part in result.unsupported_parts)


def test_unused_hidden_style_does_not_create_a_gap():
    document = office_document()
    unused = document.styles.add_style('SyntheticUnusedHidden', WD_STYLE_TYPE.PARAGRAPH)
    unused.font.hidden = True
    result = parse(saved(document))
    assert len(result.anchors) == 3
    assert result.unsupported_parts == ()


@pytest.mark.parametrize('property_name', ['vanish', 'webHidden'])
def test_document_default_hidden_is_filtered(property_name):
    def hide(root):
        rpr = root.find(f'{{{W}}}docDefaults/{{{W}}}rPrDefault/{{{W}}}rPr')
        ET.SubElement(rpr, f'{{{W}}}{property_name}')
    result = parse(edited(saved(office_document()), {'word/styles.xml': hide}))
    assert result.anchors == ()
    assert any(':hidden:' in part for part in result.unsupported_parts)


@pytest.mark.parametrize('dependency', ['cycle', 'missing'])
def test_unresolved_used_style_dependency_is_manual_and_not_evidence(dependency):
    document = office_document()
    first = document.styles.add_style('SyntheticFirst', WD_STYLE_TYPE.PARAGRAPH)
    second = document.styles.add_style('SyntheticSecond', WD_STYLE_TYPE.PARAGRAPH)
    first.base_style = second
    second.base_style = first
    document.add_paragraph('SYNTHETIC uncertain CNY 765432.', style=first)
    data = saved(document)
    if dependency == 'missing':
        def remove(root):
            root.remove(next(node for node in root if node.get(f'{{{W}}}styleId') == 'SyntheticSecond'))
        data = edited(data, {'word/styles.xml': remove})
    result = parse(data)
    assert all('765432' not in anchor.quote for anchor in result.anchors)
    assert any('style_dependency' in part for part in result.unsupported_parts)
    assert result.quality_issues


@pytest.mark.parametrize('inherited', [False, True])
def test_used_numbering_is_explicit_manual_dependency(inherited):
    document = office_document()
    paragraph = document.add_paragraph('SYNTHETIC numbered payment CNY 6200.')
    if inherited:
        paragraph.style = document.styles['List Number']
    else:
        numpr = OxmlElement('w:numPr')
        numid = OxmlElement('w:numId')
        numid.set(qn('w:val'), '5')
        numpr.append(numid)
        paragraph._p.get_or_add_pPr().append(numpr)
    result = parse(saved(document))
    assert any(anchor.quote == 'SYNTHETIC numbered payment CNY 6200.' for anchor in result.anchors)
    assert any('numbering' in part and 'manual_required' in part for part in result.unsupported_parts)
    assert any('NUMBERING_NOT_SUPPORTED' in issue for issue in result.quality_issues)


