@pytest.mark.parametrize('mismatch', ['type', 'relationship', 'root', 'content'])
def test_style_identity_requires_type_relationship_and_actual_content(mismatch):
    def wrong_type(root):
        next(node for node in root if node.get('PartName') == '/word/styles.xml').set('ContentType', 'application/xml')
    def wrong_relationship(root):
        next(node for node in root if node.get('Target') == 'styles.xml').set('Type', 'urn:synthetic:unknown')
    def wrong_content(root):
        ET.SubElement(root, f'{{{W}}}customContractObject').text = 'SYNTHETIC unread promise'
    edits = {
        'type': {'[Content_Types].xml': wrong_type},
        'relationship': {'word/_rels/document.xml.rels': wrong_relationship},
        'root': {'word/styles.xml': b'<notStyles/>'},
        'content': {'word/styles.xml': wrong_content},
    }
    result = parse(edited(saved(office_document()), edits[mismatch]))
    assert 'word/styles.xml' in result.unsupported_parts
    assert 'word/styles.xml:unsupported' in result.parts


