@pytest.mark.parametrize('baseline,expected', [
    (BaselineView.ACCEPTED_VIEW, 'SYNTHETIC new CNY 6200.'),
    (BaselineView.REJECTED_VIEW, 'SYNTHETIC old CNY 4100.'),
])
def test_baseline_selection_stays_explicit_and_revision_gap_remains(baseline, expected):
    def revisions(root):
        paragraph = root.find(f'{{{W}}}body/{{{W}}}p')
        for child in list(paragraph):
            paragraph.remove(child)
        for wrapper, tag, value in [('del', 'delText', 'SYNTHETIC old CNY 4100.'), ('ins', 't', 'SYNTHETIC new CNY 6200.')]:
            revision = ET.SubElement(paragraph, f'{{{W}}}{wrapper}')
            run = ET.SubElement(revision, f'{{{W}}}r')
            ET.SubElement(run, f'{{{W}}}{tag}').text = value
    result = parse(edited(saved(office_document()), {'word/document.xml': revisions}), baseline)
    assert result.anchors[0].quote == expected
    assert any('revisions' in part for part in result.unsupported_parts)


def test_metadata_is_not_a_filename_allowlist():
    data = saved(office_document())
    with ZipFile(BytesIO(data)) as package:
        styles = package.read('word/styles.xml')
    def rename_type(root):
        next(node for node in root if node.get('PartName') == '/word/styles.xml').set('PartName', '/word/synthetic-styles.xml')
    def rename_relation(root):
        next(node for node in root if node.get('Target') == 'styles.xml').set('Target', 'synthetic-styles.xml')
    renamed = edited(data, {'[Content_Types].xml': rename_type,
                           'word/_rels/document.xml.rels': rename_relation,
                           'word/synthetic-styles.xml': styles})
    # Remove the old member as well: an unreferenced extra is correctly unsupported.
    with ZipFile(BytesIO(renamed)) as package:
        parts = {name: package.read(name) for name in package.namelist() if name != 'word/styles.xml'}
    output = BytesIO()
    with ZipFile(output, 'w', compression=ZIP_DEFLATED) as package:
        for name, value in parts.items():
            package.writestr(name, value)
    result = parse(output.getvalue())
    assert result.unsupported_parts == ()
    assert 'word/synthetic-styles.xml:metadata_read' in result.parts


