@pytest.mark.parametrize('location', ['run_properties', 'defaults'])
def test_ambiguous_visibility_properties_do_not_enter_evidence(location):
    def duplicate_run(root):
        run = root.find(f'{{{W}}}body/{{{W}}}p/{{{W}}}r')
        run.insert(0, ET.Element(f'{{{W}}}rPr'))
        hidden = ET.Element(f'{{{W}}}rPr')
        ET.SubElement(hidden, f'{{{W}}}vanish')
        run.insert(1, hidden)
    def duplicate_default(root):
        defaults = ET.SubElement(root, f'{{{W}}}docDefaults')
        props = ET.SubElement(ET.SubElement(defaults, f'{{{W}}}rPrDefault'), f'{{{W}}}rPr')
        ET.SubElement(props, f'{{{W}}}vanish')
    edits = {'word/document.xml': duplicate_run} if location == 'run_properties' else {'word/styles.xml': duplicate_default}
    result = parse(edited(saved(office_document()), edits))
    assert all('14200' not in anchor.quote for anchor in result.anchors)
    assert any('hidden' in part or 'style_dependency' in part for part in result.unsupported_parts)


